```yaml
name: Open Data Commitment Eligibility
on:
  pull_request:
    branches:
      - dev
    paths:
      - 'src/open-data/**'
      - 'docs/open-data.md'
      - 'docs/hubs.md'
      - 'docs/optimization-engine.md'
      - 'docs/power-bi.md'
      - 'docs/workbooks.md'
      - 'src/powershell/**'
      - 'package.json'
      - 'package-lock.json'
      - '.github/workflows/opendata-commitment-eligibility.yml'
permissions: 
  contents: write
  pull-requests: write
  statuses: write
  id-token: write
jobs:
  validate:
    runs-on: ubuntu-latest
    steps:
    - uses: actions/checkout@v3
      with:
        ref: ${{ github.event.pull_request.head.ref }}
    - name: Validate Open Data Commitment Eligibility
      shell: pwsh
      run: |
        # Validate that all required files exist for the Open Data commitment
        $requiredFiles = @(
            'src/open-data/commitment.csv',
            'src/open-data/commitment.json',
            'docs/open-data.md',
            'docs/hubs.md',
            'docs/optimization-engine.md',
            'docs/power-bi.md',
            'docs/workbooks.md'
        )

        foreach ($file in $requiredFiles) {
            if (-not (Test-Path $file)) {
                Write-Error "Required file missing: $file"
                exit 1
            }
        }

        # Validate PowerShell module structure
        if (-not (Test-Path 'src/powershell/Modules')) {
            Write-Error "PowerShell module directory missing"
            exit 1
        }

        # Validate package.json contains correct dependencies
        $packageJson = Get-Content package.json | ConvertFrom-Json
        if ($packageJson.name -ne "ftk") {
            Write-Error "Invalid package name in package.json"
            exit 1
        }

        Write-Host "All validation checks passed"

        # Run lint tests
        Write-Host "Running lint tests..."
        try {
            Invoke-ScriptAnalyzer -Path src/powershell -Recurse -ErrorAction Stop
            Write-Host "Lint tests passed"
        } catch {
            Write-Error "Lint tests failed: $_"
            exit 1
        }

        # Run unit tests
        Write-Host "Running unit tests..."
        try {
            Invoke-Pester -Path src/powershell/Tests -Output Detailed -ErrorAction Stop
            Write-Host "Unit tests passed"
        } catch {
            Write-Error "Unit tests failed: $_"
            exit 1
        }

        # Validate documentation updates
        $docsUpdated = $false
        $docsFiles = @('docs/open-data.md', 'docs/hubs.md', 'docs/optimization-engine.md', 'docs/power-bi.md', 'docs/workbooks.md')
        foreach ($docFile in $docsFiles) {
            if (Test-Path $docFile) {
                $content = Get-Content $docFile -Raw
                if ($content -match "recommendations" -or $content -match "ARG-based" -or $content -match "custom recommendation") {
                    $docsUpdated = $true
                    break
                }
            }
        }

        if (-not $docsUpdated) {
            Write-Warning "Documentation does not appear to reference new recommendations features"
        }

        Write-Host "Validation completed successfully"
    - name: Test Open Data Commitment
      id: test
      shell: pwsh
      run: |
        # Test the Open Data commitment functionality
        Write-Host "Testing Open Data commitment functionality..."

        # Run the build script to ensure everything works
        try {
            .\src\scripts\Build-OpenData.ps1 -PowerShell
            Write-Host "Open Data build successful"
        } catch {
            Write-Error "Open Data build failed: $_"
            exit 1
        }

        # Check if any changes were made to the open data files
        $openDataChanged = $false
        $openDataFiles = @('src/open-data/commitment.csv', 'src/open-data/commitment.json')
        foreach ($file in $openDataFiles) {
            if (Test-Path $file) {
                $content = Get-Content $file -Raw
                if ($content.Length -gt 0) {
                    $openDataChanged = $true
                    break
                }
            }
        }

        if ($openDataChanged) {
            Write-Host "Open data files have been updated"
        } else {
            Write-Warning "No changes detected in open data files"
        }

        Write-Host "Commitment testing completed"
    - uses: actions/github-script@v7
      if: failure()
      with:
        github-token: ${{secrets.GITHUB_TOKEN}}
        script: |
          github.rest.issues.createComment({
            issue_number: context.issue.number,
            owner: context.repo.owner,
            repo: context.repo.repo,
            body: '⚠️ Open Data Commitment Eligibility validation failed. Please review the workflow logs.'
          })
```

